/**
 * The site's generated files, written from the Installed extensions by `scripts/generate.ts` (also run by
 * `belay serve` and `pnpm dev` in web/, and after `pnpm install`):
 * - route stubs: `web/src/app/(browse)/(<id>)/…`, one per route file under `extensions/<id>/web/`, re-exporting it,
 *   and a `.gitignore` that ignores the folder;
 * - `src/extensions.generated.ts` and `web/src/lib/extensions*.generated.ts`: each layer's manifests, imported statically;
 * - `web/tsconfig.extensions.json`: the site's `include`, with each installed extension's `web/`.
 * A file is rewritten only when its text changes. Deleting is limited to stubs: files headed as generated, inside a
 * `(<id>)` folder whose name is a valid id.
 */
import { existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, rmdirSync, unlinkSync, watch, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { ID, installedIds, REPO, type ExtensionId } from './extension-ids.ts';

const ROUTE_FILE = /^(page|layout|route|not-found|loading|error|template|default)\.(tsx?|jsx?)$/;
const ROUTE_EXPORTS = new Set(['default', 'metadata', 'generateMetadata', 'viewport', 'generateViewport', 'generateStaticParams', 'GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']);
const SEGMENT_CONFIG = new Set(['dynamic', 'dynamicParams', 'revalidate', 'fetchCache', 'runtime', 'preferredRegion', 'maxDuration']);
const STUB_HEADER = '// Generated from extensions/';
const IGNORE_HEADER = '# Generated for extensions/';
const LIB_HEADER = '// Generated by scripts/generate.ts from the installed extensions: don\'t edit.';
const BASE_INCLUDE = ['next-env.d.ts', 'src/**/*.ts', 'src/**/*.tsx', '.next/types/**/*.ts', '.next/dev/types/**/*.ts'];

/** Each layer's manifest file in an extension's folder, and what it exports into the generated list. */
const LAYERS = [
  { out: 'src/extensions.generated.ts', source: 'cli/manifest.ts', legacy: 'src/extensions/<id>/manifest.ts', lists: { MANIFESTS: 'manifest' } },
  { out: 'web/src/lib/extensions.generated.ts', source: 'web/_lib/manifest.ts', lists: { MANIFESTS: 'manifest' } },
  { out: 'web/src/lib/extensions.server.generated.ts', source: 'web/_lib/manifest.server.ts', lists: { KINDS: 'server', SLOTS: 'slots' } },
  { out: 'web/src/lib/extensions.client.generated.ts', source: 'web/_components/manifest.client.tsx', lists: { KINDS: 'client', SLOTS: 'slots' } },
  { out: 'web/src/lib/extensions.markdown.generated.ts', source: 'web/_lib/markdown.ts', record: { HANDLERS: 'markdown' } },
] as const;
type Layer = (typeof LAYERS)[number];

const posix = (p: string) => p.replaceAll('\\', '/');
const spec = (from: string, to: string) => {
  const p = posix(relative(dirname(from), to));
  return p.startsWith('.') ? p : `./${p}`;
};
const alias = (id: ExtensionId, name: string) => `${id.replaceAll('-', '_')}_${name}`;

export const browseDir = (root: string) => join(root, 'web', 'src', 'app', '(browse)');
const extWeb = (root: string, id: ExtensionId) => join(root, 'extensions', id, 'web');
const stubRoot = (root: string, id: ExtensionId) => join(browseDir(root), `(${id})`);

/** Whether a file's text is one this module wrote. */
export const isGenerated = (text: string) => text.startsWith(STUB_HEADER) || text.startsWith(IGNORE_HEADER) || text.startsWith(LIB_HEADER);

/**
 * The names a route file exports that Next reads, `default` first. Throws on route segment config, which Next reads
 * only from the route file itself, and on a file exporting none of them.
 */
export function routeExports(src: string, where: string): string[] {
  const names = new Set<string>();
  if (/^\s*export\s+default\b/m.test(src)) names.add('default');
  for (const m of src.matchAll(/^\s*export\s+(?:async\s+)?(?:function\*?|const|let|var|class)\s+([\w$]+)/gm)) names.add(m[1]);
  for (const m of src.matchAll(/^\s*export\s*\{([^}]*)\}/gm)) {
    for (const part of m[1].split(',')) {
      const name = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/).at(-1);
      if (name) names.add(name);
    }
  }
  const config = [...names].filter((n) => SEGMENT_CONFIG.has(n));
  if (config.length) throw new Error(`${where}: route segment config (${config.join(', ')}) is read only from the route file, which is a generated stub here`);
  const used = [...names].filter((n) => ROUTE_EXPORTS.has(n)).sort((a, b) => Number(b === 'default') - Number(a === 'default') || a.localeCompare(b));
  if (!used.length) throw new Error(`${where}: exports nothing a route file uses`);
  return used;
}

const isClient = (src: string) => /^["']use client["']/.test(src.replace(/^(?:\s|\/\/[^\n]*|\/\*[\s\S]*?\*\/)*/, ''));

/** The stub for `extensions/<id>/web/<rel>`, written at `stub`. */
export function stubSource(id: ExtensionId, rel: string, src: string, stub: string, target: string): string {
  const names = routeExports(src, `extensions/${id}/web/${rel}`);
  return [`${STUB_HEADER}${id}/web/${rel}: edit that file.`, ...(isClient(src) ? ['"use client";'] : []), `export { ${names.join(', ')} } from "${spec(stub, target)}";`, ''].join('\n');
}

/** Route files under `dir`, relative to it, skipping private (`_`) folders. */
function routeFiles(dir: string, rel = ''): string[] {
  const out: string[] = [];
  for (const e of readdirSync(join(dir, rel), { withFileTypes: true })) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory() && !e.name.startsWith('_') && e.name !== 'node_modules') out.push(...routeFiles(dir, r));
    else if (e.isFile() && ROUTE_FILE.test(e.name)) out.push(r);
  }
  return out;
}

/** Where an extension's layer file is: its own folder, else where it was until its code moved there. */
function layerFile(root: string, id: ExtensionId, layer: Layer): string | undefined {
  const legacy = 'legacy' in layer ? join(root, layer.legacy.replace('<id>', id)) : join(stubRoot(root, id), layer.source.slice('web/'.length));
  return [join(root, 'extensions', id, layer.source), legacy].find((f) => existsSync(f));
}

function layerSource(root: string, ids: readonly ExtensionId[], layer: Layer): string {
  const out = join(root, layer.out);
  const names = Object.entries('lists' in layer ? layer.lists : layer.record);
  const found = ids.flatMap((id) => {
    const file = layerFile(root, id, layer);
    return file ? [{ id, file }] : [];
  });
  const imports = found.map(({ id, file }) => `import { ${[...new Set(names.map(([, n]) => n))].map((n) => `${n} as ${alias(id, n)}`).join(', ')} } from "${spec(out, file)}";`);
  const exports = names.map(([name, imported]) =>
    'lists' in layer
      ? `export const ${name} = [${found.map(({ id }) => alias(id, imported)).join(', ')}] as const;`
      : `export const ${name} = { ${found.map(({ id }) => `${JSON.stringify(id)}: ${alias(id, imported)}`).join(', ')} } as const;`,
  );
  return [LIB_HEADER, ...imports, '', ...exports, ''].join('\n');
}

function tsconfigSource(ids: readonly ExtensionId[]): string {
  const include = [...BASE_INCLUDE, ...ids.flatMap((id) => [`../extensions/${id}/web/**/*.ts`, `../extensions/${id}/web/**/*.tsx`, `../extensions/${id}/test/site/*.ts`])];
  return `${LIB_HEADER}\n${JSON.stringify({ include }, null, 2)}\n`;
}

/** Every generated file's path and text for `ids`. */
export function planFiles(root: string, ids: readonly ExtensionId[]): Map<string, string> {
  const files = new Map<string, string>();
  for (const id of ids) {
    if (!ID.test(id)) throw new Error(`'${id}' isn't a valid extension id`);
    const web = extWeb(root, id);
    if (!existsSync(web)) continue;
    const stubs = stubRoot(root, id);
    for (const rel of routeFiles(web)) {
      const stub = join(stubs, rel);
      const target = join(web, rel);
      files.set(stub, stubSource(id, rel, readFileSync(target, 'utf8'), stub, target));
    }
    files.set(join(stubs, '.gitignore'), `${IGNORE_HEADER}${id}/web: every file here is a stub.\n*\n`);
  }
  for (const layer of LAYERS) files.set(join(root, layer.out), layerSource(root, ids, layer));
  files.set(join(root, 'web', 'tsconfig.extensions.json'), tsconfigSource(ids));
  return files;
}

/** Generated files under `dir` (symlinks neither followed nor touched) that `keep` doesn't list. */
function staleStubs(dir: string, keep: ReadonlySet<string>): string[] {
  const out: string[] = [];
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (lstatSync(p).isSymbolicLink()) continue;
    if (e.isDirectory()) out.push(...staleStubs(p, keep));
    else if (e.isFile() && !keep.has(p) && isGenerated(readFileSync(p, 'utf8'))) out.push(p);
  }
  return out;
}

/** Removes `dir`, then each parent up to and including `top`, while empty. */
function pruneEmpty(dir: string, top: string): void {
  while (dir.startsWith(top) && readdirSync(dir).length === 0) {
    rmdirSync(dir);
    dir = dirname(dir);
  }
}

export interface Generated {
  written: string[];
  removed: string[];
}

/**
 * Writes the generated files for the installed extensions and removes stubs that no route file or installed
 * extension backs any more. Refuses, before writing anything, to overwrite a file that isn't generated.
 */
export function generate(root = REPO, ids: readonly ExtensionId[] = installedIds(root)): Generated {
  const files = planFiles(root, ids);
  for (const file of files.keys()) {
    if (existsSync(file) && !isGenerated(readFileSync(file, 'utf8'))) throw new Error(`${posix(relative(root, file))} isn't generated: refusing to overwrite it`);
  }
  const written: string[] = [];
  for (const [file, text] of files) {
    if (existsSync(file) && readFileSync(file, 'utf8') === text) continue;
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, text);
    written.push(file);
  }
  const removed: string[] = [];
  const browse = browseDir(root);
  if (existsSync(browse)) {
    for (const e of readdirSync(browse, { withFileTypes: true })) {
      const id = /^\((.+)\)$/.exec(e.name)?.[1];
      if (!e.isDirectory() || !id || !ID.test(id)) continue;
      const top = join(browse, e.name);
      for (const stale of staleStubs(top, new Set(files.keys()))) {
        unlinkSync(stale);
        pruneEmpty(dirname(stale), top);
        removed.push(stale);
      }
    }
  }
  return { written: written.map((f) => posix(relative(root, f))), removed: removed.map((f) => posix(relative(root, f))) };
}

/** One line for what `generate` changed, or null when nothing did. */
export function describe({ written, removed }: Generated): string | null {
  const parts = [written.length && `wrote ${written.length}`, removed.length && `removed ${removed.length}`].filter(Boolean);
  return parts.length ? `belay: generated files: ${parts.join(', ')}` : null;
}

/** Regenerates on every change under `extensions/` (but its packages' node_modules); returns a stop function. */
export function watchExtensions(root = REPO, log: (line: string) => void = console.error): () => void {
  let timer: NodeJS.Timeout | undefined;
  const watcher = watch(join(root, 'extensions'), { recursive: true }, (_event, name) => {
    if (name && /(^|[\\/])node_modules([\\/]|$)/.test(name)) return;
    clearTimeout(timer);
    timer = setTimeout(() => {
      try {
        const line = describe(generate(root));
        if (line) log(line);
      } catch (e) {
        log(`belay: ${(e as Error).message}`);
      }
    }, 100);
  });
  return () => {
    clearTimeout(timer);
    watcher.close();
  };
}
